CREATE POLICY "Public update for funded_projects" ON public.funded_projects FOR UPDATE USING (true);
CREATE POLICY "Public delete for funded_projects" ON public.funded_projects FOR DELETE USING (true);
ALTER TABLE public.consultancy_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read for consultancy_projects" ON public.consultancy_projects FOR SELECT USING (true);
CREATE POLICY "Public insert for consultancy_projects" ON public.consultancy_projects FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update for consultancy_projects" ON public.consultancy_projects FOR UPDATE USING (true);
CREATE POLICY "Public delete for consultancy_projects" ON public.consultancy_projects FOR DELETE USING (true);
ALTER TABLE public.research_supervisors ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read for research_supervisors" ON public.research_supervisors FOR SELECT USING (true);
CREATE POLICY "Public insert for research_supervisors" ON public.research_supervisors FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update for research_supervisors" ON public.research_supervisors FOR UPDATE USING (true);
CREATE POLICY "Public delete for research_supervisors" ON public.research_supervisors FOR DELETE USING (true);
ALTER TABLE public.research_scholars ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read for research_scholars" ON public.research_scholars FOR SELECT USING (true);
CREATE POLICY "Public insert for research_scholars" ON public.research_scholars FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update for research_scholars" ON public.research_scholars FOR UPDATE USING (true);
CREATE POLICY "Public delete for research_scholars" ON public.research_scholars FOR DELETE USING (true);
ALTER TABLE public.research_awards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read for research_awards" ON public.research_awards FOR SELECT USING (true);
CREATE POLICY "Public insert for research_awards" ON public.research_awards FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update for research_awards" ON public.research_awards FOR UPDATE USING (true);
CREATE POLICY "Public delete for research_awards" ON public.research_awards FOR DELETE USING (true);
ALTER TABLE public.faculty_counts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read for faculty_counts" ON public.faculty_counts FOR SELECT USING (true);
CREATE POLICY "Public insert for faculty_counts" ON public.faculty_counts FOR INSERT WITH CHECK (true);
CREATE POLICY "Public update for faculty_counts" ON public.faculty_counts FOR UPDATE USING (true);
CREATE POLICY "Public delete for faculty_counts" ON public.faculty_counts FOR DELETE USING (true);

